                    this.ConnectMQTList();
                    this.TimerCheckInternet.Start();
                }

                Common.LoadDefualtInfo();
                MainClass.BranchCode = Common.GetBranchCode(MainClass.BranchNo);
                new Thread(Common.GetOnlineVersionInfo).Start();
