                deleteCommand.Parameters.AddWithValue("@Dbname", dbName);
                deleteCommand.ExecuteNonQuery();

                MessageBox.Show("تم الحذف بنجاح", "نجاح", MessageBoxButton.OK, MessageBoxImage.Information);
                loadDB_by_DbAutoName();
